steps.reference:
function solve(s) {
  const last = new Map();
  let left = 0, best = 0;
  for (let i = 0; i < s.length; i++) {
    if (last.has(s[i])) left = Math.max(left, last.get(s[i]) + 1);
    last.set(s[i], i);
    best = Math.max(best, i - left + 1);
  }
  return best;
}

