steps.reference:
function solve(graph, start, goal) {
  const dist = Array(graph.length).fill(-1);
  const q = [start]; dist[start] = 0;
  for (let head=0; head<q.length; head++) {
    const u=q[head];
    if (u===goal) return dist[u];
    for (const v of graph[u]) if (dist[v]===-1) {
      dist[v]=dist[u]+1; q.push(v);
    }
  }
  return -1;
}

