function solve(s) {
  const st=[], pairs={")":"(","]":"[","}":"{"};
  for (const c of s) {
    if ("([{".includes(c)) st.push(c);
    else if (st.pop()!==pairs[c]) return false;
  }
  return st.length===0;
}

