steps.reference:
function solve(root) {
  if (!root) return 0;
  const stack=[[root,1]]; let best=0;
  while(stack.length) {
    const [node,d]=stack.pop(); best=Math.max(best,d);
    if(node.left) stack.push([node.left,d+1]);
    if(node.right) stack.push([node.right,d+1]);
  }
  return best;
}

