function solve(root){if(!root)return [];const q=[root],out=[];let head=0;while(head<q.length){const end=q.length,level=[];while(head<end){const n=q[head++];level.push(n.val);if(n.left)q.push(n.left);if(n.right)q.push(n.right)}out.push(level)}return out}

